function SetAllEventListeners(){$(".nav-tabs").scrollingTabs({cssClassLeftArrow:"mdi mdi-arrow-left-bold",cssClassRightArrow:"mdi mdi-arrow-right-bold"});let elementsTabArray=DOMRegex(/^tab\_/);elementsTabArray.forEach(function(elem){elem.addEventListener("click",SetTabClick)})}function SetTabClick(evt){let attrs=evt.target.attributes;let selected_tab=attrs["data-name"].nodeValue;window.socket.emit("change_display_tab",{data:selected_tab})}